import AppKit

/// Polls the general pasteboard's changeCount and reports newly copied image data (text copies are ignored).
@MainActor
final class PasteboardWatcher: ObservableObject {
    @Published var isCapturing = true

    /// Called with (data, file extension, frontmost app name) whenever a new image is copied.
    var onImage: ((Data, String, String?) -> Void)?

    private let pasteboard = NSPasteboard.general
    private var lastChange: Int
    private var timer: Timer?

    /// Markers apps use for passwords and other sensitive or auto-generated content.
    private let skipTypes: [NSPasteboard.PasteboardType] = [
        .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.ConcealedType"),
        .init("org.nspasteboard.AutoGeneratedType"),
    ]

    /// Preferred image types, in order; image data wins over file URLs on mixed pasteboards.
    private let imageTypes: [(NSPasteboard.PasteboardType, String)] = [
        (.png, "png"),
        (.init("public.jpeg"), "jpg"),
        (.tiff, "tiff"),
    ]

    init() {
        lastChange = NSPasteboard.general.changeCount
    }

    func start() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.poll() }
        }
    }

    /// Call after the app itself writes to the pasteboard so the write is not re-captured.
    func ignoreCurrentChange() {
        lastChange = pasteboard.changeCount
    }

    private func poll() {
        let change = pasteboard.changeCount
        guard change != lastChange else { return }
        lastChange = change
        guard isCapturing, let types = pasteboard.types else { return }
        if types.contains(where: skipTypes.contains) { return }
        for (type, ext) in imageTypes where types.contains(type) {
            if let data = pasteboard.data(forType: type), !data.isEmpty {
                onImage?(data, ext, NSWorkspace.shared.frontmostApplication?.localizedName)
                return
            }
        }
    }
}
